'use strict';
const parties={Ap:{name:'Arbeiderpartiet',color:'#df3e46',logo:'ap.png'},H:{name:'Høyre',color:'#2678be',logo:'hoyre.png'},Sp:{name:'Senterpartiet',color:'#299755',logo:'sp-symbol.png'},FrP:{name:'Fremskrittspartiet',color:'#253c73',logo:'frp.png'},KrF:{name:'Kristelig Folkeparti',color:'#e9ae22',logo:'krf.png'},V:{name:'Venstre',color:'#007d82',logo:'v-symbol.svg'},SV:{name:'Sosialistisk Venstreparti',color:'#be3653',logo:'sv.png'},R:{name:'Rødt',color:'#a82329',logo:'r.svg'},MDG:{name:'Miljøpartiet De Grønne',color:'#63932d',logo:'mdg.svg'},SOL:{name:'Solrenningslista',color:'#766286'},Andre:{name:'Andre',color:'#8993a3'}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=n=>n.toLocaleString('nb-NO',{minimumFractionDigits:1,maximumFractionDigits:1});
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('nb-NO',{day:'numeric',month:'long',year:'numeric'});
const logo=(p,party='')=>p.logo?`<img class="party-logo ${party==='H'?'party-h':''}" src="assets/logos/${p.logo}" alt="${esc(p.name)}">`:'<span class="local" aria-label="Solrenningslista">SOL</span>';

const bergenCandidates=[
 {party:'H',label:'Høyre',acronym:'H',name:'Chris Jørgen Knudsen Rødland',status:'Valgt byrådslederkandidat · nr. 1 i listeinnstillingen',image:'assets/candidates/chris-rodland.jpg',credit:'Foto: Andrew M. S. Buller',source:'https://hoyre.no/bergen/aktuelt/komiteens-innstilling-er-klar/'},
 {party:'Ap',label:'Arbeiderpartiet',acronym:'Ap',name:'Linn Kristin Engø',status:'Innstilt på 1. plass · endelig valg 31. oktober',image:'assets/candidates/linn-engo.jpg',credit:'Foto: Hans Jørgen Brun',source:'https://apibergen.arbeiderpartiet.no/nyheter/nomini/'},
 {party:'FrP',label:'Frp',acronym:'FrP',name:'Toppkandidat ikke valgt ennå',status:'Nominasjon pågår',source:'https://www.frp.no/nyheter/lokalt/bergen-frps-valgliste-2027-2031'},
 {party:'SV',label:'SV',acronym:'SV',name:'Toppkandidat ikke valgt ennå',status:'Nominasjonsmøte planlagt i januar',source:'https://bergen.sv.no/lokalvalget-2027/'},
 {party:'MDG',label:'MDG',acronym:'MDG',name:'Katrine Nødtvedt',status:'Innstilt som førstekandidat',image:'assets/candidates/katrine-nodtvedt.jpg',source:'https://bergen.mdg.no/nyhet/innstillingen-til-nominasjonsmotet-er-klar/'},
 {party:'BL',label:'Bergenslisten',acronym:'BL',name:'Toppkandidat ikke valgt ennå',status:'Ikke offentlig avklart'},
 {party:'V',label:'Venstre',acronym:'V',name:'Toppkandidat ikke valgt ennå',status:'Ikke offentlig avklart'},
 {party:'R',label:'Rødt',acronym:'R',name:'Toppkandidat ikke valgt ennå',status:'Ikke offentlig avklart'},
 {party:'Sp',label:'Senterpartiet',acronym:'Sp',name:'Toppkandidat ikke valgt ennå',status:'Ikke offentlig avklart'},
 {party:'KrF',label:'KrF',acronym:'KrF',name:'Toppkandidat ikke valgt ennå',status:'Ikke offentlig avklart'},
 {party:'PP',label:'Pensjonistpartiet',acronym:'PP',name:'Toppkandidat ikke valgt ennå',status:'Ikke offentlig avklart'}
];

function renderBergenCandidates(){
 const host=document.querySelector('#candidate-grid');
 host.innerHTML=bergenCandidates.map(c=>{const p=parties[c.party]||{name:c.label,color:c.party==='BL'?'#e77e23':c.party==='PP'?'#555d69':'#526779'};const mark=p.logo?`<span class="candidate-logo">${logo(p,c.party)}</span>`:`<span class="candidate-logo candidate-wordmark" style="--party:${p.color}">${esc(c.acronym)}</span>`;return `<article class="candidate-card" style="--party:${p.color}"><div class="candidate-card-top">${mark}<span class="candidate-party">${esc(c.label)}</span></div>${c.image?`<img class="candidate-photo" src="${c.image}" alt="${esc(c.name)}" loading="lazy">`:`<div class="candidate-placeholder" aria-hidden="true"><span class="placeholder-mark">${esc(c.acronym)}</span><span>${c.name==='Katrine Nødtvedt'?'Bilde kommer':'Kandidat ikke valgt'}</span></div>`}<div class="candidate-copy"><h3>${esc(c.name)}</h3>${c.credit?`<small>${esc(c.credit)}</small>`:''}</div></article>`}).join('');
}

function renderElection(result){
 if(!result)return '<p>Valgresultatet kunne ikke lastes.</p>';
 const maxPercent=Math.max(...result.results.map(r=>r.percent),1);
 const rows=result.results.filter(r=>r.percent>0||r.seats>0).sort((a,b)=>b.percent-a.percent).map(r=>{
  const p=parties[r.party]||parties.Andre,label={H:'Høyre',V:'Venstre',R:'Rødt'}[r.party]||r.party;
  return `<div class="bar-row" aria-label="${esc(label)}: ${pct(r.percent)} prosent, ${r.seats} mandater"><span class="bar-label">${esc(label)}</span><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="--party:${p.color};--value:${r.percent/maxPercent*100}%"></div></div><span class="bar-value">${pct(r.percent)}</span><span class="bar-seats">${r.seats}</span></div>`;
 }).join('');
 return `<section class="election-2023" aria-labelledby="election-heading"><h3 id="election-heading">Valgresultat 2023</h3><p class="visually-hidden">Valgresultat 2023 i ${esc(result.name)}: oppslutning og mandater per parti</p><div class="poll-table-head" aria-hidden="true"><span>Parti</span><span></span><span>Prosent</span><span>Mandater</span></div><div class="chart election-chart" role="group" aria-label="Valgresultat 2023 i ${esc(result.name)}">${rows}</div><div class="election-total"><span>Totalt</span><strong>${result.totalSeats}</strong></div><a class="source" href="${esc(result.source)}" target="_blank" rel="noopener">Se valgresultatet hos Poll of polls ↗</a></section>`;
}

async function start(){
 const [municipalities,geo,polls,elections]=await Promise.all(['municipalities.json','vestland.geojson','polls.json','elections-2023.json'].map(async f=>{const r=await fetch('data/'+f+(f==='polls.json'?'?v=poll-mandates-1':''));if(!r.ok)throw new Error('Data kunne ikke lastes');return r.json()}));
 const byId=new Map(municipalities.map(m=>[m.id,m]));const layers=new Map(),markers=new Map();const requested=new URLSearchParams(location.search).get('kommune');let selected=byId.has(requested)?requested:'4601';const select=document.querySelector('#municipality');select.innerHTML=municipalities.slice().sort((a,b)=>a.name.localeCompare(b.name,'nb')).map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('');
 function show(id){const m=byId.get(id);if(!m)return;selected=id;select.value=id;document.querySelector('#bergen-candidates').hidden=id!=='4601';const p=parties[m.party],poll=polls[id];for(const [key,l]of layers)l.setStyle({color:key===id?'#087c83':'#809aa8',weight:key===id?2.8:1,fillColor:parties[byId.get(key).party].color,fillOpacity:key===id?.30:.13});for(const [key,marker]of markers)marker.getElement()?.classList.toggle('selected',key===id);
 const bars=poll?Object.entries(poll.values).map(([party,value])=>{const pp=parties[party],label=party==='H'?'Høyre':party==='R'?'Rødt':party==='V'?'Venstre':party,mandates=poll.seats?.[party]??'–';return `<div class="bar-row" aria-label="${esc(pp.name)}: ${pct(value)} prosent, ${mandates} mandater"><span class="bar-label">${label}</span><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="--party:${pp.color};--value:${value/Math.max(...Object.values(poll.values))*100}%"></div></div><span class="bar-value">${pct(value)}</span><span class="bar-seats" title="${mandates} mandater">${mandates}</span></div>`}).join(''):'';
 const pollTotal=poll?Object.values(poll.seats||{}).reduce((sum,seats)=>sum+Number(seats||0),0):0;
 const pollContent=poll?`<div class="poll-head"><h3>Siste kommunemåling</h3></div><div class="chart" role="group" aria-label="Partienes oppslutning i prosent og mandater"><div class="poll-table-head" aria-hidden="true"><span>Parti</span><span></span><span>Prosent</span><span>Mandater</span></div>${bars}</div><div class="poll-total"><span>Totalt</span><strong>${pollTotal}</strong></div><p class="poll-meta">${date(poll.date)} · ${esc(poll.client)}</p><a class="poll-source" href="${esc(poll.source)}" target="_blank" rel="noopener">Se målingen hos Poll of polls ↗</a>`:`<div class="empty"><div class="empty-symbol" aria-hidden="true">▂ ▅ ▃</div><h3>Ingen måling registrert i 2026</h3><p>Vi fant ingen kommunemåling fra 2026 for ${esc(m.name)} hos Poll of polls ved siste kontroll.</p><a href="https://www.pollofpolls.no/?cmd=Maling&filter=kommune" target="_blank" rel="noopener">Se alle kommunemålinger ↗</a></div>`;
 document.querySelector('#detail-content').innerHTML=`<div class="municipality-summary"><h2>${esc(m.name)}</h2><div class="mayor"><div class="mayor-logo">${logo(p)}</div><div><small>${m.acting?'Fungerende ordfører':'Ordfører'}</small><p><strong>${esc(m.mayor)}</strong></p></div></div>${m.note?`<p class="mayor-note">${esc(m.note)}</p>`:''}</div><div class="detail-data-grid"><section class="poll-panel" aria-label="Siste kommunemåling">${pollContent}</section>${renderElection(elections[id])}</div>`;}
 const map=L.map('map',{zoomControl:false,scrollWheelZoom:!window.matchMedia('(pointer:coarse)').matches,minZoom:6,maxZoom:13,zoomSnap:.25});L.control.zoom({position:'topright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);
 const boundary=L.geoJSON(geo,{style:f=>({color:'#809aa8',weight:1,fillColor:parties[byId.get(f.properties.kommunenummer).party].color,fillOpacity:.13}),onEachFeature:(feature,layer)=>{const id=feature.properties.kommunenummer,m=byId.get(id);layers.set(id,layer);layer.bindTooltip(`<strong>${esc(m.name)}</strong>${esc(m.mayor)} (${esc(parties[m.party].name)})`,{sticky:true,direction:'top'});layer.on({click:()=>show(id)})}}).addTo(map);
 const bounds=boundary.getBounds();function fit(){map.fitBounds(bounds,{padding:[24,25],animate:false})}fit();for(const m of municipalities){const p=parties[m.party];const marker=L.marker([m.point[1],m.point[0]],{icon:L.divIcon({className:'party-marker',html:`<span class="marker-inner">${logo(p)}</span>`,iconSize:[30,30],iconAnchor:[15,15]}),title:`${m.name}: ${m.mayor} (${p.name})`,alt:`${m.name}: ${m.mayor} (${p.name})`,keyboard:true,riseOnHover:true}).addTo(map);marker.bindTooltip(`<strong>${esc(m.name)}</strong>${esc(m.mayor)} (${esc(p.name)})`,{direction:'top',offset:[0,-13]});marker.on({click:()=>show(m.id)});markers.set(m.id,marker)}select.addEventListener('change',()=>{show(select.value);const point=byId.get(select.value).point;map.panTo([point[1],point[0]])});document.querySelector('#reset').addEventListener('click',fit);new ResizeObserver(()=>{map.invalidateSize();fit()}).observe(document.querySelector('.map-shell'));renderBergenCandidates();show(selected);
}
start().catch(error=>{console.error(error);document.querySelector('#map-error').hidden=false;document.querySelector('#map-error').textContent='Kartet kunne ikke lastes. Prøv å laste siden på nytt.';document.querySelector('#detail-content').innerHTML='<p>Kommuneinformasjonen kunne ikke lastes. Prøv igjen om litt.</p>'});

